INSERT INTO risk_rules (rule_id, rule_code, rule_name, description, applies_to, metric_name, metric_unit, lookback_hours, threshold_value, midpoint_value, weight, score_ceiling, rule_version, effective_from, effective_to, is_active, owner_role, approved_by_role) VALUES
('RULE-001', 'VELOCITY_SPIKE', 'Velocity spike', 'Count customer-initiated debits in a 24-hour window anchored at the first debit of a burst; fires when the count reaches the threshold.', 'DEBIT transactions of type PURCHASE, ATM_WITHDRAWAL, BILL_PAYMENT, TRANSFER_OUT', 'debits in 24h window', 'COUNT', 24, 6.0000, 9.0000, 60.00, 100.00, 2, '2025-12-01', NULL, 1, 'SYSTEM_ADMINISTRATOR', 'RISK_REVIEWER'),
('RULE-002', 'NEW_DEVICE_ACTIVITY', 'New-device activity', 'Sum the debits made through a device within 48 hours of the device''s first use on the account; only devices first linked at least 7 days after account opening count as new.', 'DEBIT transactions with a device_id (digital channels)', 'EUR debited via new device within 48h', 'EUR', 48, 1000.0000, 3000.0000, 65.00, 100.00, 1, '2025-12-01', NULL, 1, 'SYSTEM_ADMINISTRATOR', 'RISK_REVIEWER'),
('RULE-003', 'CIRCULAR_TRANSFER', 'Circular transfer ring', 'Follow transfer links forward in time from each transfer; fires when funds return to the originating account through at least 3 distinct accounts within 72 hours, every hop within +/-10% of the first hop amount.', 'transfer_links (TRANSFER_OUT/TRANSFER_IN leg pairs)', 'first-hop amount of the ring', 'EUR', 72, 500.0000, 5250.0000, 75.00, 100.00, 1, '2025-12-01', NULL, 1, 'SYSTEM_ADMINISTRATOR', 'RISK_REVIEWER'),
('RULE-004', 'DORMANT_REACTIVATION', 'Dormant account reactivation', 'After a DORMANT->ACTIVE status event, sum the customer-initiated debits of the next 7 days; fires when the sum reaches the threshold.', 'account_status_history DORMANT->ACTIVE events and the account''s DEBIT transactions', 'EUR debited within 7 days of reactivation', 'EUR', 168, 2000.0000, 11000.0000, 70.00, 100.00, 1, '2025-12-01', NULL, 1, 'SYSTEM_ADMINISTRATOR', 'RISK_REVIEWER'),
('RULE-005', 'HIGH_AMOUNT_VS_PROFILE', 'High amount vs. customer profile', 'Divide a single card, cash or bill-payment debit by the customer''s KYC expected_max_txn_amount; fires when the ratio reaches the threshold.', 'DEBIT transactions of type PURCHASE, ATM_WITHDRAWAL, BILL_PAYMENT', 'amount / KYC expected max transaction', 'RATIO', 0, 3.0000, 6.0000, 55.00, 92.00, 2, '2025-12-01', NULL, 1, 'SYSTEM_ADMINISTRATOR', 'RISK_REVIEWER'),
('RULE-006', 'ROUND_AMOUNT_STRUCTURING', 'Round-amount structuring (retired)', 'Retired on 2025-12-31 after the annual rule review (superseded by RULE-005); kept for traceability and not evaluated.', 'DEPOSIT transactions', 'round-amount deposits in 7 days', 'COUNT', 168, 3.0000, 4.5000, 50.00, 100.00, 1, '2024-01-01', '2025-12-31', 0, 'SYSTEM_ADMINISTRATOR', 'RISK_REVIEWER');
